    "studio.index": "STUDIO", "studio.heading": "Turning different crafts and everyday observations into worlds we can explore together.", "studio.body": "Mugio is an indie game team where illustration, UI/UX, engineering, and writing meet. We turn experience from different fields—and what we notice in daily life—into game stories, visuals, and new forms of interaction.", "studio.founded": "Founded", "studio.based": "Based in", "studio.taiwan": "Taiwan", "studio.craftsLabel": "Disciplines", "studio.craftsValue": "Illustration · UI/UX · Engineering · Writing", "studio.workingOn": "Current title", "studio.moments": "Ditto MOMENTS",
    "hero.kicker": "TAIWAN INDEPENDENT GAME STUDIO · SINCE 2025", "hero.explore": "Meet our first title", "hero.media": "Press assets", "hero.collageTop": "OBSERVE · DRAW · BUILD · WRITE", "hero.currentLabel": "OUR FIRST TITLE", "hero.japaneseTitle": "てくてく日和", "hero.artAlt": "Key art for Ditto MOMENTS", "hero.screenAlt": "Metro scene from Ditto MOMENTS", "hero.dogAlt": "Naotaro, a dog-like Momentling",
    "game.index": "GAME", "game.heading": "Find small wonders tucked into a familiar commute.", "game.summary": "Ditto MOMENTS is a cozy point-and-click adventure set in everyday life. Follow office worker Mugi through the city, find the scattered Momentlings, restore an exchange diary, and rediscover the understanding two roommates once missed.", "game.aboutLabel": "ABOUT THE GAME", "game.longIntro": "Mugi discovers that her roommate Shiro has fallen into a mysterious sleep. Their exchange diary has lost its words and memories, while the Momentlings that once lived inside have scattered across the city. Players read puzzle-like diary clues, arrange metro stations, convenience stores, and breakfast shops into a daily route, then observe scenes, make choices, play bite-sized mini-games, and photograph Momentlings. Each discovery restores diary fragments and character memories, helping Mugi understand Shiro—and see her own habits and choices from a new angle.", "game.storyLabel": "STORY", "game.storyHeading": "After an argument, the roommates’ ordinary day stops in its tracks.", "game.storyBody": "Mugi leaves home angry after an argument. When she returns, Shiro is still frozen in the same pose as that morning. Papers hang motionless in the air, and their exchange diary has lost every word. Guided by Beigo, Mugi learns that the diary’s Momentlings have scattered across the city.", "game.storyBody2": "Follow the clues through metro stations, convenience stores, breakfast shops, and the office. Piece together forgotten moments, and help Mugi understand how Shiro sees everyday life.", "game.originLabel": "ORIGIN", "game.originHeading": "Looking at the subtle differences inside commuting, work, and shared life.", "game.originBody": "Ditto MOMENTS grew from our observations of commuting, work, and living together. Mugio brings together backgrounds in illustration, product design, software development, and writing. We turn small habits and frictions—the kind that quietly shape relationships—into events players can observe and take part in.",
    "facts.platformLabel": "Planned platforms", "facts.languageLabel": "Languages", "facts.languageValue": "Traditional Chinese · English · Japanese", "facts.sessionLabel": "Play session", "facts.sessionValue": "About 3–5 minutes", "facts.statusLabel": "Status", "facts.statusValue": "In development",
