    "features.label": "HOW IT PLAYS", "features.routeTitle": "Plan each day", "features.routeBody": "Use diary clues to arrange metro stations, breakfast shops, and street corners into a route.", "features.observeTitle": "Observe and choose", "features.observeBody": "Click through scenes and respond to situations where small choices reveal something personal.", "features.photoTitle": "Photograph Momentlings", "features.photoBody": "Capture curious creatures that reflect the habits of city life.", "features.diaryTitle": "Restore the diary", "features.diaryBody": "Unlock missing words and character memories as the story gradually returns.",
