const languageConfig = {
  "zh-TW": { htmlLang: "zh-Hant", logoKey: "zhSrc", route: "/zh-TW", ogLocale: "zh_TW" },
  en: { htmlLang: "en", logoKey: "enSrc", route: "/en", ogLocale: "en_US" },
  ja: { htmlLang: "ja", logoKey: "jaSrc", route: "/ja", ogLocale: "ja_JP" }
};

let activeLanguage = "zh-TW";
let lightboxSourceButton = null;

function getPageType() {
  const pageType = document.body?.dataset.page;
  return ["early-bird", "tgs2026", "privacy"].includes(pageType) ? pageType : "home";
}

function getLocalizedPath(language, pageType = getPageType()) {
  const suffixes = { "early-bird": "/early-bird", tgs2026: "/tgs2026", privacy: "/privacy" };
  const suffix = suffixes[pageType] || "";
  return `${languageConfig[language].route}${suffix}`;
}

function translate(key, language = activeLanguage) {
  return translations[language]?.[key] ?? translations["zh-TW"][key] ?? key;
}

function updateMenuLabel() {
  const menuToggle = document.querySelector(".menu-toggle");
  if (!menuToggle) return;
  const isOpen = menuToggle.getAttribute("aria-expanded") === "true";
  menuToggle.setAttribute("aria-label", translate(isOpen ? "a11y.menuClose" : "a11y.menuOpen"));
}

function setLanguage(language, { updateUrl = true } = {}) {
  if (!languageConfig[language]) return;
  activeLanguage = language;
  document.documentElement.lang = languageConfig[language].htmlLang;
  const pageType = getPageType();
  const metaPrefixes = { "early-bird": "early.meta", tgs2026: "tgs.meta", privacy: "privacy.meta" };
  const metaPrefix = metaPrefixes[pageType] || "meta";
  document.title = translate(`${metaPrefix}.title`, language);
  const description = translate(`${metaPrefix}.description`, language);
  document.querySelector('meta[name="description"]')?.setAttribute("content", description);
  document.querySelector('meta[property="og:title"]')?.setAttribute("content", document.title);
  document.querySelector('meta[property="og:description"]')?.setAttribute("content", description);
  document.querySelector("[data-og-locale]")?.setAttribute("content", languageConfig[language].ogLocale);
  const localizedPath = getLocalizedPath(language, pageType);
  const isFilePreview = window.location.protocol === "file:";
  const localeUrl = isFilePreview
    ? localizedPath
    : new URL(localizedPath, window.location.origin).href;
  document.querySelector("[data-og-url]")?.setAttribute("content", localeUrl);
  document.querySelectorAll("[data-i18n]").forEach((element) => { element.textContent = translate(element.dataset.i18n, language); });
  document.querySelectorAll("[data-i18n-aria-label]").forEach((element) => { element.setAttribute("aria-label", translate(element.dataset.i18nAriaLabel, language)); });
  document.querySelectorAll("[data-i18n-alt]").forEach((element) => { element.setAttribute("alt", translate(element.dataset.i18nAlt, language)); });
  document.querySelectorAll("[data-i18n-placeholder]").forEach((element) => { element.setAttribute("placeholder", translate(element.dataset.i18nPlaceholder, language)); });
  document.querySelectorAll("[data-lang]").forEach((link) => {
    link.href = isFilePreview ? `?lang=${link.dataset.lang}` : getLocalizedPath(link.dataset.lang, pageType);
    if (link.dataset.lang === language) link.setAttribute("aria-current", "page");
    else link.removeAttribute("aria-current");
  });
  document.querySelectorAll("[data-home-link]").forEach((link) => {
    link.href = isFilePreview ? `index.html?lang=${language}` : languageConfig[language].route;
  });
  document.querySelectorAll('[data-page-link="early-bird"]').forEach((link) => {
    link.href = isFilePreview ? `early-bird.html?lang=${language}` : `${languageConfig[language].route}/early-bird`;
  });
  document.querySelectorAll('[data-page-link="privacy"]').forEach((link) => {
    link.href = isFilePreview ? `privacy.html?lang=${language}` : `${languageConfig[language].route}/privacy`;
  });
  document.querySelectorAll("[data-tgs-early-link]").forEach((link) => {
    const earlyBirdPath = isFilePreview ? `early-bird.html?lang=${language}&` : `${languageConfig[language].route}/early-bird?`;
    link.href = `${earlyBirdPath}utm_source=tgs&utm_medium=landing_page&utm_campaign=tgs2026`;
  });
  document.querySelectorAll('[data-page-link="tgs2026"]').forEach((link) => {
    link.href = isFilePreview ? `tgs2026.html?lang=${language}` : `${languageConfig[language].route}/tgs2026`;
  });
  document.querySelectorAll("[data-locale-logo]").forEach((logo) => {
    logo.src = logo.dataset[languageConfig[language].logoKey];
  });
  document.querySelector("[data-canonical]")?.setAttribute("href", localeUrl);
  updateMenuLabel();
  try { localStorage.setItem("mugio-language", language); } catch (_) {}
  if (updateUrl) {
    const url = new URL(window.location.href);
    if (isFilePreview) {
      url.searchParams.set("lang", language);
    } else {
      url.pathname = localizedPath;
      url.search = "";
    }
    history.replaceState({}, "", url);
  }
}

function getInitialLanguage() {
  const url = new URL(window.location.href);
  const routeLanguage = url.pathname.split("/").filter(Boolean)[0];
  if (routeLanguage && languageConfig[routeLanguage]) return routeLanguage;
  const queryLanguage = url.searchParams.get("lang");
  if (queryLanguage && languageConfig[queryLanguage]) return queryLanguage;
  try {
    const storedLanguage = localStorage.getItem("mugio-language");
    if (storedLanguage && languageConfig[storedLanguage]) return storedLanguage;
  } catch (_) {}
  return getPageType() === "tgs2026" ? "ja" : "zh-TW";
}

const menuToggle = document.querySelector(".menu-toggle");
const mobileMenu = document.querySelector(".mobile-menu");
function closeMenu() {
  if (!menuToggle || !mobileMenu) return;
  menuToggle.setAttribute("aria-expanded", "false");
  menuToggle.classList.remove("is-open");
  mobileMenu.hidden = true;
  document.body.classList.remove("menu-open");
  updateMenuLabel();
}
menuToggle?.addEventListener("click", () => {
  const willOpen = menuToggle.getAttribute("aria-expanded") !== "true";
  menuToggle.setAttribute("aria-expanded", String(willOpen));
  menuToggle.classList.toggle("is-open", willOpen);
  mobileMenu.hidden = !willOpen;
  document.body.classList.toggle("menu-open", willOpen);
  updateMenuLabel();
});
mobileMenu?.querySelectorAll("a").forEach((link) => link.addEventListener("click", closeMenu));
window.addEventListener("resize", () => { if (window.innerWidth > 900) closeMenu(); });

const header = document.querySelector("[data-site-header]");
function updateHeader() { header?.classList.toggle("is-scrolled", window.scrollY > 20); }
updateHeader();
window.addEventListener("scroll", updateHeader, { passive: true });

function alignHashTarget() {
  if (!window.location.hash) return;
  const anchor = document.querySelector(window.location.hash);
  if (!anchor) return;
  const root = document.documentElement;
  const previousBehavior = root.style.scrollBehavior;
  root.style.scrollBehavior = "auto";
  anchor.scrollIntoView({ block: "start" });
  root.style.scrollBehavior = previousBehavior;
}

window.addEventListener("load", () => {
  alignHashTarget();
  window.setTimeout(alignHashTarget, 160);
});

document.querySelectorAll("[data-reveal-delay]").forEach((element) => element.style.setProperty("--reveal-delay", `${element.dataset.revealDelay}ms`));
const revealElements = document.querySelectorAll(".reveal");
if ("IntersectionObserver" in window) {
  const revealObserver = new IntersectionObserver((entries, observer) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      entry.target.classList.add("is-visible");
      observer.unobserve(entry.target);
    });
  }, { threshold: 0.1, rootMargin: "0px 0px -4%" });
  revealElements.forEach((element) => revealObserver.observe(element));
} else {
  revealElements.forEach((element) => element.classList.add("is-visible"));
}

const lightbox = document.querySelector("[data-lightbox]");
const lightboxImage = lightbox?.querySelector("img");
const lightboxCaption = lightbox?.querySelector("figcaption");
const lightboxClose = lightbox?.querySelector(".lightbox-close");
document.querySelectorAll("[data-lightbox-src]").forEach((button) => {
  button.addEventListener("click", () => {
    if (!lightbox || !lightboxImage || !lightboxCaption) return;
    const caption = translate(button.dataset.captionKey);
    lightboxSourceButton = button;
    lightboxImage.src = button.dataset.lightboxSrc;
    lightboxImage.alt = caption;
    lightboxCaption.textContent = caption;
    lightbox.showModal();
  });
});
function closeLightbox() {
  if (!lightbox?.open) return;
  lightbox.close();
  lightboxSourceButton?.focus();
}
lightboxClose?.addEventListener("click", closeLightbox);
lightbox?.addEventListener("click", (event) => { if (event.target === lightbox) closeLightbox(); });

document.querySelectorAll("[data-early-bird-form]").forEach((earlyBirdForm) => {
  earlyBirdForm.addEventListener("submit", (event) => {
    event.preventDefault();
    if (!earlyBirdForm.reportValidity()) return;
    const formData = new FormData(earlyBirdForm);
    const platform = formData.get("platform") || "unsure";
    const lines = [`${translate("early.mailEmail")}: ${formData.get("email") || ""}`];
    if (earlyBirdForm.querySelector('[name="name"]')) {
      lines.push(`${translate("early.mailName")}: ${formData.get("name") || "—"}`);
    }
    if (earlyBirdForm.querySelector('[name="platform"]')) {
      lines.push(`${translate("early.mailPlatform")}: ${translate(`early.platform.${platform}`)}`);
    }
    lines.push(`${translate("early.mailLanguage")}: ${languageConfig[activeLanguage].htmlLang}`);
    if (formData.get("source")) {
      lines.push(`${translate("early.mailSource")}: ${formData.get("source")}`);
    }
    const mailto = `mailto:hello@mugio.studio?subject=${encodeURIComponent(translate("early.mailSubject"))}&body=${encodeURIComponent(lines.join("\n"))}`;
    const earlyBirdStatus = earlyBirdForm.querySelector("[data-early-bird-status]");
    if (earlyBirdStatus) earlyBirdStatus.textContent = translate("early.formStatus");
    if (typeof window.gtag === "function") {
      const urlParams = new URL(window.location.href).searchParams;
      window.gtag("event", "generate_lead", {
        form_id: "early_bird_registration",
        form_name: "early_bird_registration",
        lead_source: urlParams.get("utm_source") || "website",
        preferred_platform: platform,
        site_language: activeLanguage
      });
    }
    window.setTimeout(() => { window.location.href = mailto; }, 80);
  });
});

document.querySelectorAll("[data-current-year]").forEach((element) => { element.textContent = new Date().getFullYear(); });
setLanguage(getInitialLanguage(), { updateUrl: false });
